css:
.custom-radio-group {
  --transDur: 0.3s;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1em;
}
.custom-radio-group form {
  display: flex;
  gap: 0.1em;
  max-width: 20em;
  margin: auto;
  padding: 0 1em;
}
.custom-radio-group .radio-label {
  width: 100px;
  position: relative;
  display: block;
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.custom-radio-group .radio-input {
  background-image: linear-gradient(
    #ffffff 33%,
    #414751 58%,
    #837b52,
    #c5baa1,
    #c3adaa
  );
  border-radius: 0;
  box-shadow:
    0.1em 0 0 #2726267f inset,
    -0.1em 0 0 #27262600 inset,
    0 0.1em 0 #afa490 inset,
    0 -0.1em 0 #ffffff3f,
    0 0.2em 0.5em #0000007f,
    0 -0.1em 0 #926086 inset,
    -0.1em -0.2em 0 #ffffff7f inset;
  cursor: pointer;
  display: block;
  margin-bottom: 0.5em;
  width: 100%;
  height: 0.8em;
  transition: box-shadow var(--transDur) ease-in-out;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}
.custom-radio-group .radio-input:checked {
  background-image: linear-gradient(
    #ffffff 33%,
    #414751 58%,
    #827a7b,
    #c0b6ac,
    #c3adaa
  );
  box-shadow:
    0.1em 0 0 #272626af inset,
    -0.1em 0 0 #272626 inset,
    0 0.1em 0 #847a62 inset,
    0 -0.1em 0 #ffffff3f,
    0 0.1em 0 #ffffff7f,
    0 -0.1em 0 #722257 inset,
    -0.1em -0.2em 0 #ffffff7f inset;
}
.custom-radio-group .radio-input:checked + span {
  opacity: 1;
}
.custom-radio-group .radio-input:focus {
  outline: transparent;
}
.custom-radio-group .radio-input + span {
  opacity: 0.65;
  transition: opacity var(--transDur) ease-in-out;
}
/* First and last input specific styles */
.custom-radio-group .radio-label:first-child .radio-input {
  border-radius: 0.4em 0 0 0.4em;
}
.custom-radio-group .radio-label:last-child .radio-input {
  border-radius: 0 0.4em 0.4em 0;
}

@media (prefers-color-scheme: dark) {
  .custom-radio-group {
    background-color: #212121;
  }
  .custom-radio-group .radio-input {
    background-image: linear-gradient(
      #3a3a3a 33%,
      #1c1e22 58%,
      #4a4639,
      #7a7468,
      #7a6e6b
    );
    box-shadow:
      0.1em 0 0 #0000007f inset,
      -0.1em 0 0 #00000000 inset,
      0 0.1em 0 #5a5448 inset,
      0 -0.1em 0 #ffffff1f,
      0 0.2em 0.5em #0000007f,
      0 -0.1em 0 #4d3347 inset,
      -0.1em -0.2em 0 #ffffff3f inset;
  }
  .custom-radio-group .radio-input:checked {
    background-image: linear-gradient(
      #4a4a4a 33%,
      #2c2e32 58%,
      #5a5453,
      #7a7671,
      #7a6e6b
    );
    box-shadow:
      0.1em 0 0 #000000af inset,
      -0.1em 0 0 #000000 inset,
      0 0.1em 0 #4a4539 inset,
      0 -0.1em 0 #ffffff1f,
      0 0.1em 0 #ffffff3f,
      0 -0.1em 0 #3d1230 inset,
      -0.1em -0.2em 0 #ffffff3f inset;
  }
  .custom-radio-group .radio-input + span {
    color: #e0e0e0;
  }
}
